package com.example.starter.water;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

class InfiltrationEngineTests {

    private static long t(String iso) { return WaterService.toNanos(Instant.parse(iso)); }
    private static InfiltrationEngine.Event ev(String key, String iso, String deduct) {
        return new InfiltrationEngine.Event(key, t(iso), new BigDecimal(deduct));
    }

    @Test void recoveryCappedAtCapacity() {
        var o = InfiltrationEngine.evaluate(10, 2, t("2026-10-20T09:00:00Z"),
            List.of(ev("a", "2026-10-20T12:00:00Z", "8")));
        assertNull(o.deficit());
        assertEquals(0, new BigDecimal("2").compareTo(o.steps().get(0).balanceAfter()));
    }

    @Test void sameHourDeductsInKeyOrder() {
        var o = InfiltrationEngine.evaluate(10, 2, t("2026-10-20T09:00:00Z"),
            List.of(ev("b", "2026-10-20T10:00:00Z", "6"), ev("a", "2026-10-20T10:00:00Z", "5")));
        assertNull(o.deficit());
        assertEquals("a", o.steps().get(0).allocationKey());
        assertEquals(0, new BigDecimal("5").compareTo(o.steps().get(0).balanceAfter()));
        assertEquals("b", o.steps().get(1).allocationKey());
        assertEquals(0, BigDecimal.ZERO.compareTo(o.steps().get(1).balanceAfter()));
    }

    @Test void deficitReportedAtFirstNegativeStep() {
        // 题干合成：C=10 R=2，10 点 8+1，11 点 4 → 11 点缺口 1
        var o = InfiltrationEngine.evaluate(10, 2, t("2026-10-20T09:00:00Z"),
            List.of(ev("a1", "2026-10-20T10:00:00Z", "8"),
                    ev("a2", "2026-10-20T11:00:00Z", "4"),
                    ev("a3", "2026-10-20T10:00:00Z", "1")));
        assertNotNull(o.deficit());
        assertEquals("a2", o.deficit().allocationKey());
        assertEquals(0, new BigDecimal("-1").compareTo(o.deficit().balanceAfter()));
        assertEquals(3, o.steps().size());
    }

    @Test void partialHourRecoveryFloored() {
        // 启用 09:30，11:00 事件间隔 1.5 小时 → 只计 1 小时恢复
        var o = InfiltrationEngine.evaluate(10, 2, t("2026-10-20T09:30:00Z"),
            List.of(ev("a", "2026-10-20T10:00:00Z", "9"), ev("b", "2026-10-20T11:00:00Z", "3")));
        // 10:00: min(10, 10+0)=10-9=1；11:00: min(10, 1+2)=3-3=0
        assertNull(o.deficit());
        assertEquals(0, BigDecimal.ZERO.compareTo(o.steps().get(1).balanceAfter()));
    }

    @Test void emptyEventsKeepCapacity() {
        var o = InfiltrationEngine.evaluate(10, 2, t("2026-10-20T09:00:00Z"), List.of());
        assertNull(o.deficit());
        assertEquals(0, new BigDecimal("10").compareTo(o.finalBalance(10)));
    }
}
```

